import{_ as e,o as a,c as l,ah as s}from"./chunks/framework.CPHJ30oF.js";const p=JSON.parse('{"title":"17-dockerignore与Build-Cache构建效率提升指南","description":"","frontmatter":{},"headers":[{"level":2,"title":"引言","slug":"引言","link":"#引言","children":[]},{"level":2,"title":"1. 为什么构建效率重要","slug":"_1-为什么构建效率重要","link":"#_1-为什么构建效率重要","children":[]},{"level":2,"title":"2. .dockerignore：控制构建上下文","slug":"_2-dockerignore-控制构建上下文","link":"#_2-dockerignore-控制构建上下文","children":[{"level":3,"title":"为什么要忽略这些文件","slug":"为什么要忽略这些文件","link":"#为什么要忽略这些文件","children":[]}]},{"level":2,"title":"3. Build Cache：让镜像构建更“增量”","slug":"_3-build-cache-让镜像构建更-增量","link":"#_3-build-cache-让镜像构建更-增量","children":[{"level":3,"title":"关键原则","slug":"关键原则","link":"#关键原则","children":[]}]},{"level":2,"title":"4. Dockerfile 写法优化","slug":"_4-dockerfile-写法优化","link":"#_4-dockerfile-写法优化","children":[{"level":3,"title":"推荐写法","slug":"推荐写法","link":"#推荐写法","children":[]},{"level":3,"title":"避免写法","slug":"避免写法","link":"#避免写法","children":[]}]},{"level":2,"title":"5. 实用命令与工具","slug":"_5-实用命令与工具","link":"#_5-实用命令与工具","children":[]},{"level":2,"title":"6. 常见误区","slug":"_6-常见误区","link":"#_6-常见误区","children":[]},{"level":2,"title":"7. 进阶技巧","slug":"_7-进阶技巧","link":"#_7-进阶技巧","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]}],"relativePath":"docker/17-dockerignore与Build-Cache构建效率提升指南.md","filePath":"docker/17-dockerignore与Build-Cache构建效率提升指南.md"}'),n={name:"docker/17-dockerignore与Build-Cache构建效率提升指南.md"};function d(r,i,h,c,t,o){return a(),l("div",null,[...i[0]||(i[0]=[s(`<h1 id="_17-dockerignore与build-cache构建效率提升指南" tabindex="-1">17-dockerignore与Build-Cache构建效率提升指南 <a class="header-anchor" href="#_17-dockerignore与build-cache构建效率提升指南" aria-label="Permalink to “17-dockerignore与Build-Cache构建效率提升指南”">​</a></h1><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to “引言”">​</a></h2><p>频繁构建 Docker 镜像时，构建速度和缓存命中率直接影响开发效率。<code>.dockerignore</code> 和 Build Cache 是两个最有效的优化点。</p><p>本篇文章从构建上下文、缓存命中和 Dockerfile 组织三个层面，讲清如何让 Docker 构建更快、更稳定。</p><h2 id="_1-为什么构建效率重要" tabindex="-1">1. 为什么构建效率重要 <a class="header-anchor" href="#_1-为什么构建效率重要" aria-label="Permalink to “1. 为什么构建效率重要”">​</a></h2><p>构建慢会带来：</p><ul><li>开发反馈周期拉长；</li><li>CI 流水线变慢；</li><li>测试和部署成本升高；</li><li>迭代体验下降。</li></ul><p>优化构建并不是“折腾技巧”，而是提升整个交付链路效率。</p><h2 id="_2-dockerignore-控制构建上下文" tabindex="-1">2. <code>.dockerignore</code>：控制构建上下文 <a class="header-anchor" href="#_2-dockerignore-控制构建上下文" aria-label="Permalink to “2. .dockerignore：控制构建上下文”">​</a></h2><p>Docker 构建时会把当前目录上下文发送给守护进程。如果上下文包含大量无关文件，构建会变慢。</p><p>常见 <code>.dockerignore</code> 内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>node_modules</span></span>
<span class="line"><span>.git</span></span>
<span class="line"><span>logs</span></span>
<span class="line"><span>*.log</span></span>
<span class="line"><span>dist</span></span>
<span class="line"><span>.idea</span></span>
<span class="line"><span>.vscode</span></span>
<span class="line"><span>.DS_Store</span></span></code></pre></div><h3 id="为什么要忽略这些文件" tabindex="-1">为什么要忽略这些文件 <a class="header-anchor" href="#为什么要忽略这些文件" aria-label="Permalink to “为什么要忽略这些文件”">​</a></h3><ul><li><code>node_modules</code>：依赖应在镜像内部安装；</li><li><code>.git</code>：版本控制元数据不需要；</li><li>日志与临时文件：与镜像运行无关；</li><li>产物目录：如果你构建时会重新生成。</li></ul><h2 id="_3-build-cache-让镜像构建更-增量" tabindex="-1">3. Build Cache：让镜像构建更“增量” <a class="header-anchor" href="#_3-build-cache-让镜像构建更-增量" aria-label="Permalink to “3. Build Cache：让镜像构建更“增量””">​</a></h2><p>Docker 会缓存每个镜像层的构建结果。只要某层之前的输入没有改变，Docker 就会复用缓存。</p><h3 id="关键原则" tabindex="-1">关键原则 <a class="header-anchor" href="#关键原则" aria-label="Permalink to “关键原则”">​</a></h3><ul><li>把变化少的步骤放到前面；</li><li>把变化频繁的步骤放到后面；</li><li>合理拆分 <code>COPY</code> 和 <code>RUN</code>。</li></ul><p>示例：</p><div class="language-dockerfile"><button title="Copy Code" class="copy"></button><span class="lang">dockerfile</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COPY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> package*.json ./</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">RUN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> npm install</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COPY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> . .</span></span></code></pre></div><p>只要依赖文件没变，<code>npm install</code> 就能复用缓存。</p><h2 id="_4-dockerfile-写法优化" tabindex="-1">4. Dockerfile 写法优化 <a class="header-anchor" href="#_4-dockerfile-写法优化" aria-label="Permalink to “4. Dockerfile 写法优化”">​</a></h2><h3 id="推荐写法" tabindex="-1">推荐写法 <a class="header-anchor" href="#推荐写法" aria-label="Permalink to “推荐写法”">​</a></h3><div class="language-dockerfile"><button title="Copy Code" class="copy"></button><span class="lang">dockerfile</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> node:20-alpine</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WORKDIR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /app</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COPY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> package*.json ./</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">RUN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> npm install --production</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COPY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> . .</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CMD</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;node&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;index.js&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><h3 id="避免写法" tabindex="-1">避免写法 <a class="header-anchor" href="#避免写法" aria-label="Permalink to “避免写法”">​</a></h3><div class="language-dockerfile"><button title="Copy Code" class="copy"></button><span class="lang">dockerfile</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COPY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> . .</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">RUN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> npm install</span></span></code></pre></div><p>这种写法会导致每次源码改动都重新执行依赖安装。</p><h2 id="_5-实用命令与工具" tabindex="-1">5. 实用命令与工具 <a class="header-anchor" href="#_5-实用命令与工具" aria-label="Permalink to “5. 实用命令与工具”">​</a></h2><ul><li><code>docker build --progress=plain .</code>：查看详细构建日志；</li><li><code>docker build --no-cache .</code>：禁用缓存；</li><li><code>docker build --target builder .</code>：只构建指定阶段；</li><li><code>dive &lt;image&gt;</code>：分析镜像层和体积；</li><li><code>docker buildx</code>：构建跨平台镜像并优化缓存。</li></ul><h2 id="_6-常见误区" tabindex="-1">6. 常见误区 <a class="header-anchor" href="#_6-常见误区" aria-label="Permalink to “6. 常见误区”">​</a></h2><ul><li>误以为 <code>.dockerignore</code> 只能影响镜像大小。它同样影响构建速度；</li><li>误以为缓存总是自动命中。构建上下文变化会导致失效；</li><li>误以为层数越少越好。合理的层划分更重要。</li></ul><h2 id="_7-进阶技巧" tabindex="-1">7. 进阶技巧 <a class="header-anchor" href="#_7-进阶技巧" aria-label="Permalink to “7. 进阶技巧”">​</a></h2><ul><li>使用多阶段构建把临时文件隔离到构建阶段；</li><li>对大文件和生成目录单独处理；</li><li>复用构建缓存到共享环境（如 CI 缓存）；</li><li>用 <code>docker buildx create --use</code> 提前构建增强缓存效果。</li></ul><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h2><p><code>.dockerignore</code> 和 Build Cache 是 Docker 构建优化的两大基础。控制构建上下文、优化 Dockerfile 顺序、理解缓存原理，才能让镜像构建从“每次重做”变成“增量复用”。这对快速迭代和高效 CI 都至关重要。</p>`,35)])])}const g=e(n,[["render",d]]);export{p as __pageData,g as default};
